def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter

    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # A full, uniform line of a non-background color marks the repeat period.
    row_marks = [(r, g[r][0]) for r in range(h)
                 if g[r][0] != bg and all(x == g[r][0] for x in g[r])]
    col_marks = [(c, g[0][c]) for c in range(w)
                 if g[0][c] != bg and all(g[r][c] == g[0][c] for r in range(h))]

    if row_marks:
        period = row_marks[0][0] + 1
        if len(row_marks) > 1:
            period = row_marks[1][0] - row_marks[0][0]
        for c in range(w):
            for r in range(h):
                if g[r][c] == bg:
                    vals = [g[k][c] for k in range(r % period, h, period)
                            if g[k][c] != bg]
                    if vals:
                        g[r][c] = vals[0]
    elif col_marks:
        period = col_marks[0][0] + 1
        if len(col_marks) > 1:
            period = col_marks[1][0] - col_marks[0][0]
        for r in range(h):
            for c in range(w):
                if g[r][c] == bg:
                    vals = [g[r][k] for k in range(c % period, w, period)
                            if g[r][k] != bg]
                    if vals:
                        g[r][c] = vals[0]

    return g
